import { useEffect, useRef } from 'react'
import { Icon } from '@/design-system/Icon'
import { useI18n } from '@/i18n'
import { useDictation } from './useDictation'
import './voice.css'

/**
 * A microphone next to a text field.
 *
 * Sits beside the input rather than replacing it, because dictation fails in
 * ordinary ways — a noisy car, a browser without a recogniser, a denied
 * permission — and a feature that can fail must never be the only door.
 *
 * What it produces goes into the field, where it can be read and corrected
 * before anything is saved. It is never sent anywhere by this component.
 */
export function Dictate({
  value,
  onChange,
  label,
}: {
  value: string
  onChange: (next: string) => void
  /** What is being dictated, for the screen reader. */
  label: string
}) {
  const { t } = useI18n()
  const d = useDictation()
  // The text at the moment the microphone was switched on. Dictation appends to
  // what was already typed instead of wiping it.
  const base = useRef('')

  useEffect(() => {
    if (!d.text) return
    onChange(base.current ? `${base.current} ${d.text}` : d.text)
    // `onChange` identity changes on every parent render; depending on it here
    // would re-fire this effect and duplicate the dictated text.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [d.text])

  if (!d.supported) return null

  const errKey =
    d.error === 'denied'
      ? 'voice.errDenied'
      : d.error === 'network'
        ? 'voice.errNetwork'
        : d.error === 'nospeech'
          ? 'voice.errNoSpeech'
          : 'voice.errOther'

  return (
    <div className="voice">
      <button
        type="button"
        className={`voice__btn ${d.listening ? 'voice__btn--on' : ''}`}
        aria-pressed={d.listening}
        aria-label={d.listening ? t('voice.stop') : t('voice.start', { what: label })}
        onClick={() => {
          if (d.listening) {
            d.stop()
            return
          }
          base.current = value.trim()
          d.reset()
          d.start()
        }}
      >
        <Icon name="voice" size={18} animate={d.listening} />
        <span>{d.listening ? t('voice.listening') : t('voice.dictate')}</span>
      </button>

      {/* Interim words are shown, but greyed and italic: they are the
          recogniser thinking aloud and it revises them constantly. */}
      {d.listening && d.interim && (
        <p className="voice__interim" aria-live="polite">
          {d.interim}
        </p>
      )}
      {d.listening && <p className="voice__note">{t('voice.privacy')}</p>}
      {d.error && (
        <p className="banner banner--warn" role="alert">
          {t(errKey)}
        </p>
      )}
    </div>
  )
}
